import sys
import copy
from hae.genome.schema import CompanyGenome, DepartmentGenome, AgentGenome
from hae.genome.morphogenesis import StructuralCrossoverEngine

# Construct minimal valid parents
def make_agent(role, temp=0.7):
    return AgentGenome(role=role, goal='g', backstory='b', temperature=temp)

def make_dept(dept_id, name, mandate, role='manager'):
    mgr = make_agent(role)
    return DepartmentGenome(dept_id=dept_id, name=name, mandate=mandate, manager=mgr)

def make_company(cid, depts):
    ceo = make_agent('CEO')
    return CompanyGenome(company_id=cid, ceo=ceo, departments=depts)

# Parent A: Systems Eng
